                    source={require('/assets/VolleyBallGame.png')}
                />
                <Image
                    style={styles.appdim}
                    resizeMode='contain'
                    source={require('/assets/ArcheryGame.png')}
                />
            </Pressable>
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
